function onlyDigits(value: string) {
  return value.replace(/\D/g, "");
}

// New traced silhouette — female, and eventually all genders.
// Renders every path from the source file, so the arm/torso separation and
// interior detail lines (creases, folds) show exactly as traced. Auto-crops
// to the real drawn bounding box on mount, since each traced source SVG has
// a different amount of empty margin baked into its original viewBox —
// without this, some shapes render visibly bigger/smaller than others even
// though they're meant to be shown at the same relative scale.
function TracedBodySilhouette({ id, viewBox, paths }: TracedBodyShape) {
  const groupRef = useRef<SVGGElement | null>(null);
  const [renderViewBox, setRenderViewBox] = useState(viewBox);

  useEffect(() => {
    if (!groupRef.current) return;
    try {
      const bbox = groupRef.current.getBBox();
      if (bbox.width > 0 && bbox.height > 0) {
        const padX = bbox.width * 0.06;
        const padY = bbox.height * 0.04;
        setRenderViewBox(
          `${bbox.x - padX} ${bbox.y - padY} ${bbox.width + padX * 2} ${bbox.height + padY * 2}`,
        );
      }
    } catch {
      // getBBox can throw if not yet mounted/visible — keep the fallback viewBox
    }
  }, [id]);

  const strokeScale = Number(viewBox.split(" ")[2]) || 1000;

  return (
    <svg viewBox={renderViewBox} className="w-32 h-56 shrink-0" fill="none" aria-hidden="true">
      <g ref={groupRef}>
        {paths.map((d, i) => (
          <path
            key={i}
            d={d}
            stroke="currentColor"
            strokeWidth={Math.max(1, strokeScale / 700)}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        ))}
      </g>
    </svg>
  );
}

function ImageBodyOption({
  option,
  isSelected,
  onSelect,
}: {
  option: ImageBodyShape;
  isSelected: boolean;
  onSelect: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onSelect}
      aria-pressed={isSelected}
      aria-label={option.label}
      className={`flex flex-col items-center gap-1.5 rounded-xl border py-2 px-2 shrink-0 snap-start transition-colors duration-300 ${
        isSelected
          ? "border-brand-accent text-brand-accent"
          : "border-brand-text/25 text-brand-text hover:border-brand-text/50"
      }`}
    >
      <span className="relative">
        <img src={option.src} alt="" loading="lazy" className="w-32 h-56 object-contain shrink-0" />
        <span
          className={`absolute -top-1 -right-1 flex h-6 w-6 items-center justify-center rounded-full border transition-colors duration-200 ${
            isSelected
              ? "border-brand-accent bg-brand-accent text-white"
              : "border-brand-text/25 bg-brand-bg text-transparent"
          }`}
          aria-hidden="true"
        >
          <Check size={14} strokeWidth={3} />
        </span>
      </span>
      <span className="text-[11px] leading-tight text-center max-w-32 line-clamp-2 text-current">
        {option.label}
      </span>
    </button>
  );
}

function FindYourFitPage() {
  const navigate = useNavigate();
  const { userId, checking } = useRequireSession();
  // Read after mount, so the server render and hydration agree.
  const [intent, setIntentState] = useState<Intent | null>(null);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);

  useEffect(() => {
    setIntentState(readIntent() ?? "creator");
  }, []);

  const [heightUnit, setHeightUnit] = useState<"cm" | "ftin">("cm");
  const [heightCm, setHeightCm] = useState("");
  const [heightFt, setHeightFt] = useState("");
  const [heightIn, setHeightIn] = useState("");
  const heightInRef = useRef<HTMLInputElement>(null);

  const [weightUnit, setWeightUnit] = useState<"kg" | "lbs">("kg");
  const [weight, setWeight] = useState("");

  const [gender, setGender] = useState("");
  const [bodyType, setBodyType] = useState<string | null>(null);

  const [measurementsOpen, setMeasurementsOpen] = useState(false);
  const [measurementUnit, setMeasurementUnit] = useState<"cm" | "in">("cm");
  const [measurements, setMeasurements] = useState<Record<string, string>>({});
  const [focusedMeasurementKey, setFocusedMeasurementKey] = useState<string | null>(null);

  const [bodyPhotoFile, setBodyPhotoFile] = useState<File | null>(null);
  const [bodyPhotoPreview, setBodyPhotoPreview] = useState<string | null>(null);
  const bodyPhotoInputRef = useRef<HTMLInputElement>(null);

  // Revoke on unmount only — handleBodyPhotoChange/clearBodyPhoto revoke the
  // previous URL themselves before replacing it.
  useEffect(() => {
    return () => {
      if (bodyPhotoPreview) URL.revokeObjectURL(bodyPhotoPreview);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleBodyPhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setBodyPhotoFile(file);
    setBodyPhotoPreview((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return URL.createObjectURL(file);
    });
  };

  const clearBodyPhoto = () => {
    setBodyPhotoFile(null);
    setBodyPhotoPreview((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return null;
    });
    if (bodyPhotoInputRef.current) bodyPhotoInputRef.current.value = "";
  };

  const bodyTypeOptions = gender === "Male" ? MALE_BODY_TYPE_IMAGES : FEMALE_BODY_TYPES;
  const measurementLines = gender === "Male" ? MALE_MEASUREMENT_LINES : FEMALE_MEASUREMENT_LINES;
  const measurementGuideImage = gender === "Male" ? maleMeasurementGuide : femaleMeasurementGuide;

  const handleGenderChange = (value: string) => {
    setGender(value);
    setBodyType(null);
    // Keys differ between genders (e.g. "bust" vs "chest") — carrying over the
    // other gender's stale values would just be dead data.
    setMeasurements({});
    setFocusedMeasurementKey(null);
  };

  // Mirrors SizeChartSheet's switchUnit: convert every typed value through cm
  // rather than just relabeling the unit, so switching cm/in mid-entry
  // doesn't silently change what number is saved.
  function switchMeasurementUnit(next: "cm" | "in") {
    if (next === measurementUnit) return;
    setMeasurements((prev) => {
      const out: Record<string, string> = {};
      for (const key of Object.keys(prev)) {
        const raw = prev[key];
        const num = parseFloat(raw);
        if (!raw.trim() || isNaN(num)) {
          out[key] = raw;
          continue;
        }
        const cm = displayToCm(num, measurementUnit);
        out[key] = formatMeasurement(cmToDisplay(cm, next));
      }
      return out;
    });
    setMeasurementUnit(next);
  }

  // Hands off to whats-your-style, the next step in the creator/curator
  // flows (see FLOWS in onboarding-flow.ts). It used to navigate to
  // /phone-number, which for curators sent them straight back to the step they
  // had just come from: an onboarding loop with no exit, Skip included.
  const finish = () => {
    navigate({ to: nextRoute(intent, "/find-your-fit"), replace: true });
  };

  function toNum(raw: string): number | null {
    const n = parseFloat(raw);
    return isNaN(n) ? null : n;
  }

  // A row's existence in creators/curators (not the values in it) is what
  // resolvePostAuthRedirect treats as "this account finished find-your-fit" —
  // see src/lib/auth.ts. Submit and Skip both have to write one, or an
  // account that skipped would be asked again on every future sign-in. The
  // actual body/style data lives in fit_profiles instead, keyed by owner_id
  // and shared across roles, so a person who's both creator and curator only
  // answers these questions once.
  const roleTable = intent === "curator" ? "curators" : "creators";

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!userId || saving) return;
    setSaving(true);
    setSaveError(null);

    const heightCmValue =
      heightUnit === "cm"
        ? toNum(heightCm)
        : (() => {
            const feet = toNum(heightFt);
            const inches = toNum(heightIn);
            if (feet === null && inches === null) return null;
            return ((feet ?? 0) * 12 + (inches ?? 0)) * CM_PER_INCH;
          })();

    const weightRaw = toNum(weight);
    const weightKgValue =
      weightRaw === null ? null : weightUnit === "kg" ? weightRaw : weightRaw * 0.453592;

    const measurementsCm = measurementsOpen
      ? Object.entries(measurements).reduce<Record<string, number>>((acc, [key, raw]) => {
          const n = toNum(raw);
          if (n !== null) acc[key] = displayToCm(n, measurementUnit);
          return acc;
        }, {})
      : null;

    let fullBodyPhotoUrl: string | null = null;
    if (bodyPhotoFile) {
      // Same "avatars" bucket + {owner_id}/filename convention edit-profile.tsx
      // uses for the profile picture.
      const ext = bodyPhotoFile.name.split(".").pop() || "jpg";
      const path = `${userId}/body-photo.${ext}`;
      const { error: uploadError } = await supabase.storage
        .from("avatars")
        .upload(path, bodyPhotoFile, { upsert: true });
      if (uploadError) {
        console.error("find-your-fit: failed to upload body photo", uploadError);
        setSaving(false);
        setSaveError("Couldn't upload that photo — please try again.");
        return;
      }
      fullBodyPhotoUrl = supabase.storage.from("avatars").getPublicUrl(path).data.publicUrl;
    }

    const { error: fitError } = await supabase.from("fit_profiles").upsert(
      {
        owner_id: userId,
        height_cm: heightCmValue,
        weight_kg: weightKgValue,
        gender: gender || null,
        body_type: bodyType,
        measurements_cm: measurementsCm,
        full_body_photo_url: fullBodyPhotoUrl,
      },
      { onConflict: "owner_id" },
    );

    const { error: roleError } = fitError
      ? { error: null }
      : await supabase
          .from(roleTable)
          .upsert({ owner_id: userId }, { onConflict: "owner_id", ignoreDuplicates: true });

    setSaving(false);
    if (fitError || roleError) {
      console.error("find-your-fit: failed to save", fitError || roleError);
      setSaveError("Couldn't save that — please try again.");
      return;
    }

    finish();
  };

  const handleSkip = async () => {
    if (!userId || saving) return;
    setSaving(true);
    // Only records role membership — no bare fit_profiles row on skip, since
    // whats-your-style's own upsert creates one if it's still missing by
    // then, and there's no data worth writing yet either way.
    const { error } = await supabase
      .from(roleTable)
      .upsert({ owner_id: userId }, { onConflict: "owner_id", ignoreDuplicates: true });
    setSaving(false);
    // Skipping shouldn't be able to strand someone here if the write fails —
    // worst case they're just asked again next sign-in, via
    // resolvePostAuthRedirect's own fit-profile check.
    if (error) console.error("find-your-fit: failed to record skip", error);
    finish();
  };

  if (checking) return <OnboardingChecking />;

  return (
    <OnboardingShell
      title="Find your fit"
      subtitle="Let us recommend pieces exactly your size."
      backTo={previousStep(intent, "/find-your-fit")}
      step={stepPosition(intent, "/find-your-fit")}
      onSkip={handleSkip}
    >
      <form onSubmit={handleSubmit} className="space-y-3">
        <div>
          <div className="flex items-center justify-end gap-3 mb-1.5 px-1">
            <button
              type="button"
              onClick={() => setHeightUnit("cm")}
              className={`text-[11px] uppercase tracking-widest transition-colors ${heightUnit === "cm" ? "text-brand-accent" : "text-brand-text/40"}`}
            >
              cm
            </button>
            <button
              type="button"
              onClick={() => setHeightUnit("ftin")}
              className={`text-[11px] uppercase tracking-widest transition-colors ${heightUnit === "ftin" ? "text-brand-accent" : "text-brand-text/40"}`}
            >
              ft/in
            </button>
          </div>
          {heightUnit === "cm" ? (
            <input
              type="text"
              inputMode="numeric"
              value={heightCm}
              onChange={(e) => setHeightCm(onlyDigits(e.target.value))}
              placeholder="Height (cm)"
              className="w-full rounded-full border border-brand-text/25 bg-transparent px-5 py-3.5 text-sm placeholder:text-brand-text/40 focus:outline-none focus:border-brand-accent transition-colors"
            />
          ) : (
            // Fixed-width, not flex-1 — a value here is never more than 2
            // digits, so stretching each box to half the row (like a normal
            // full-width field) left the Inches box overflowing the screen.
            <div className="flex gap-2">
              <div className="flex items-center gap-1.5 w-[108px] rounded-full border border-brand-text/25 px-4 py-3.5 focus-within:border-brand-accent transition-colors">
                <input
                  type="text"
                  inputMode="numeric"
                  value={heightFt}
                  onChange={(e) => {
                    // A person's height in feet is always one digit — advance
                    // to Inches the moment it's typed instead of making them
                    // tap over manually.
                    const digits = onlyDigits(e.target.value).slice(0, 1);
                    setHeightFt(digits);
                    if (digits.length === 1) heightInRef.current?.focus();
                  }}
                  placeholder="0"
                  className="w-6 min-w-0 bg-transparent text-sm placeholder:text-brand-text/40 focus:outline-none"
                />
                <span className="text-xs text-brand-text/40">ft</span>
              </div>
              <div className="flex items-center gap-1.5 w-[108px] rounded-full border border-brand-text/25 px-4 py-3.5 focus-within:border-brand-accent transition-colors">
                <input
                  ref={heightInRef}
                  type="text"
                  inputMode="numeric"
                  value={heightIn}
                  onChange={(e) => setHeightIn(onlyDigits(e.target.value).slice(0, 2))}
                  placeholder="0"
                  className="w-6 min-w-0 bg-transparent text-sm placeholder:text-brand-text/40 focus:outline-none"
                />
                <span className="text-xs text-brand-text/40">in</span>
              </div>
            </div>
          )}
        </div>

        <div>
          <div className="flex items-center justify-end gap-3 mb-1.5 px-1">
            <button
              type="button"
              onClick={() => setWeightUnit("kg")}
              className={`text-[11px] uppercase tracking-widest transition-colors ${weightUnit === "kg" ? "text-brand-accent" : "text-brand-text/40"}`}
            >
              kg
            </button>
            <button
              type="button"
              onClick={() => setWeightUnit("lbs")}
              className={`text-[11px] uppercase tracking-widest transition-colors ${weightUnit === "lbs" ? "text-brand-accent" : "text-brand-text/40"}`}
            >
              lbs
            </button>
          </div>
          <input
            type="text"
            inputMode="numeric"
            value={weight}
            onChange={(e) => setWeight(onlyDigits(e.target.value))}
            placeholder={weightUnit === "kg" ? "Weight (kg)" : "Weight (lbs)"}
            className="w-full rounded-full border border-brand-text/25 bg-transparent px-5 py-3.5 text-sm placeholder:text-brand-text/40 focus:outline-none focus:border-brand-accent transition-colors"
          />
        </div>

        <div className="grid grid-cols-2 gap-2" role="group" aria-label="Gender">
          {(["Female", "Male"] as const).map((option) => (
            <button
              key={option}
              type="button"
              onClick={() => handleGenderChange(option)}
              aria-pressed={gender === option}
              className={`rounded-full border px-5 py-3.5 text-sm transition-colors ${
                gender === option
                  ? "border-brand-accent bg-brand-accent text-brand-bg"
                  : "border-brand-text/25 text-brand-text/80 hover:border-brand-text/50"
              }`}
            >
              {option}
            </button>
          ))}
        </div>

        {(gender === "Female" || gender === "Male") && (
          // Only this outer container gets the accent color — everything
          // inside (image box, rows, photo uploader) keeps its own neutral
          // borders so the blue reads as "this section," not as emphasis on
          // any one field inside it.
          <div className="rounded-2xl border-2 border-brand-accent overflow-hidden text-left">
            <button
              type="button"
              onClick={() => setMeasurementsOpen((v) => !v)}
              className="w-full flex items-center justify-between px-5 py-3.5 text-sm text-brand-text/80 hover:bg-brand-text/5 transition-colors"
            >
              <span>Optional — add specific measurements</span>
              <span
                className={`transition-transform duration-200 ${measurementsOpen ? "rotate-90" : ""}`}
              >
                ›
              </span>
            </button>
            {measurementsOpen && (
              <div className="px-5 pb-5 pt-4 border-t border-brand-text/10 space-y-4">
                <div className="w-full aspect-[3/4] bg-brand-text/5 rounded-2xl p-3">
                  <img
                    src={measurementGuideImage}
                    alt={`${gender} body measurement guide`}
                    className="w-full h-full object-contain"
                  />
                </div>

                <div className="flex justify-end">
                  <div className="flex bg-brand-text/10 rounded-full p-1">
                    {(["cm", "in"] as const).map((u) => (
                      <button
                        key={u}
                        type="button"
                        onClick={() => switchMeasurementUnit(u)}
                        className={`px-3 py-1 rounded-full text-xs font-medium uppercase tracking-widest transition-colors duration-200 ${
                          measurementUnit === u
                            ? "bg-brand-accent text-brand-bg"
                            : "text-brand-text/50"
                        }`}
                      >
                        {u}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="flex flex-col gap-2.5">
                  {measurementLines.map((line) => (
                    <div
                      key={line.key}
                      className={`flex items-center justify-between gap-3 rounded-xl border px-4 py-3 transition-colors duration-150 ${
                        focusedMeasurementKey === line.key
                          ? "border-brand-accent"
                          : "border-brand-text/15"
                      }`}
                    >
                      <button
                        type="button"
                        onClick={() => setFocusedMeasurementKey(line.key)}
                        className="flex items-center gap-2 text-left min-w-0"
                      >
                        <span className="text-[11px] font-semibold text-brand-text/40 uppercase shrink-0">
                          {line.letter}
                        </span>
                        <span className="text-sm text-brand-text/90">{line.label}</span>
                      </button>
                      <div className="flex items-center gap-1.5 shrink-0">
                        <input
                          value={measurements[line.key] ?? ""}
                          onChange={(e) =>
                            setMeasurements((prev) => ({
                              ...prev,
                              [line.key]: e.target.value.replace(/[^0-9.]/g, ""),
                            }))
                          }
                          onFocus={() => setFocusedMeasurementKey(line.key)}
                          inputMode="decimal"
                          placeholder="0"
                          className="w-14 text-right text-sm outline-none bg-transparent text-brand-text"
                        />
                        <span className="text-xs text-brand-text/40">{measurementUnit}</span>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="pt-4 border-t border-brand-text/10">
                  <p className="text-sm text-brand-text/90 mb-1">Full body photo</p>
                  <p className="text-xs text-brand-text/50 mb-3">
                    Optional — helps us judge your proportions more accurately than measurements
                    alone.
                  </p>

                  {bodyPhotoPreview ? (
                    <div className="flex items-center gap-3">
                      <div className="relative w-16 aspect-[3/4] rounded-lg overflow-hidden shrink-0 border border-brand-text/15">
                        <img
                          src={bodyPhotoPreview}
                          alt="Your uploaded full body photo"
                          className="w-full h-full object-cover"
                        />
                      </div>
                      <div className="flex flex-col gap-1.5 items-start">
                        <button
                          type="button"
                          onClick={() => bodyPhotoInputRef.current?.click()}
                          className="text-xs uppercase tracking-widest text-brand-accent hover:underline"
                        >
                          Replace photo
                        </button>
                        <button
                          type="button"
                          onClick={clearBodyPhoto}
                          className="text-xs uppercase tracking-widest text-brand-text/50 hover:text-brand-text/80"
                        >
                          Remove
                        </button>
                      </div>
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => bodyPhotoInputRef.current?.click()}
                      className="w-full rounded-xl border border-dashed border-brand-text/25 py-5 text-sm text-brand-text/60 hover:border-brand-text/50 transition-colors"
                    >
                      Tap to snap a photo or upload from gallery
                    </button>
                  )}

                  <input
                    ref={bodyPhotoInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleBodyPhotoChange}
                    className="hidden"
                  />
                </div>
              </div>
            )}
          </div>
        )}

        {(gender === "Female" || gender === "Male") && (
          <div className="pt-4 text-left">
            <p className="text-sm text-brand-text/70 mb-3">Pick a close resembling body type.</p>
            <div className="flex gap-3 overflow-x-auto pb-2 -mx-1 px-1 snap-x snap-mandatory scrollbar-thin">
              {bodyTypeOptions.map((option) => (
                <ImageBodyOption
                  key={option.id}
                  option={option}
                  isSelected={bodyType === option.id}
                  onSelect={() => setBodyType(option.id)}
                />
              ))}
            </div>
          </div>
        )}

        <p className="text-xs text-brand-text/50 px-2 pt-2">
          The information collected here is strictly for content and piece recommendation and is not
          meant to be or seem intrusive or abusive in any way.
        </p>

        <FormError>{saveError}</FormError>

        <button
          type="submit"
          disabled={saving}
          className="w-full rounded-full bg-brand-accent text-brand-bg py-3.5 text-sm font-medium uppercase tracking-widest hover:bg-brand-accent/90 hover:scale-[1.01] transition-all duration-300 mt-2 disabled:opacity-60"
        >
          {saving ? "Saving…" : "Finish"}
        </button>
      </form>
    </OnboardingShell>
  );
}
